class Document(
    private val file: FileHandle,             // owned part: closed by close()
    renderer: Renderer,
) : Closeable, Renderer by renderer {         // one interface, delegated to a part
    private val parts = mutableListOf<Paragraph>()
    fun add(text: String): Paragraph = Paragraph(text).also(parts::add)
    override fun close() { parts.forEach(Paragraph::close); file.close() }
}
